#include "main.h"
#include <stdio.h>
// 조이스틱 X→PA0(IN0), Y→PA1(IN1) · ADC1 스캔 2채널 연속 변환, DMA1 Channel1 순환 · HAL_ADC_ConvHalfCpltCallback/ConvCpltCallback으로 평균 계산

/* Copy this main.c into a CubeIDE STM32F103RB project with matching
 * pin / peripheral / NVIC settings and Cube-generated IRQ / MSP files.
 * Clock: HSI PLL, APB1 timer clock = 64000000 Hz.
 * printf: SWV ITM port 0 (enable SWV in the debugger). UART uses its pins.
 * With newlib-nano, enable -u _printf_float for floating-point printf. */

ADC_HandleTypeDef hadc1;
DMA_HandleTypeDef hdma_adc1;

void SystemClock_Config(void);
void Error_Handler(void);
static void MX_GPIO_Init(void);
static void MX_DMA_Init(void);
static void MX_ADC1_Init(void);

uint16_t adc[64]; /* X,Y,X,Y,... */
volatile uint32_t avgX = 0, avgY = 0, blocks = 0;
void average(int from) {
    uint32_t x = 0, y = 0;
    for (int i = from; i < from + 32; i += 2) {
        x += adc[i];
        y += adc[i + 1];
    }
    avgX = x / 16;
    avgY = y / 16;
}
int main(void) {
    HAL_Init();
    SystemClock_Config();
    MX_GPIO_Init();
    MX_DMA_Init();
    MX_ADC1_Init();
    /* USER CODE BEGIN 2 */
    HAL_ADC_Start_DMA(&hadc1, (uint32_t*)adc, 64);
    printf("ADC DMA scan: IN0(X), IN1(Y), 32 samples per channel\n");
    /* USER CODE END 2 */
    while (1) {
        /* USER CODE BEGIN 3 */
        HAL_Delay(500);
        printf("X=%lu Y=%lu (DMA blocks=%lu)\n", avgX, avgY, blocks);
        /* USER CODE END 3 */
    }
}

